[meta]
name = Vesperholm
ambient = 0.52 0.57 0.72
fog = 0.34 0.39 0.53
fog_range = 14 84
model_range = 46
indoor_range = 26
sky = moonlit
torch = 6 0.62 0.68 0.82
start = 21 100 -90
default = ,
entity_floor = auto
edge_top = 9
edge_tex = moonstone

// Vesperholm, the Moonbound City, behind the Vesper Gate in Harrowmere's north wall at the head of the
// cathedral steps, which stands open to anyone who climbs them: the seat of the king's sister, Duchess
// Ilvane, who wed the moon on the fourth sigil so the night would never end and nothing in her city
// would die. The moon stopped over it, vast, full and pale, and has hung in the north
// over her cathedral ever since; everything under it is drowned in its light, and every soul in the
// city has thinned to a moonlit shade of itself. You come through the gate into the Glimmering Cave,
// where the moon-crystal grows and the Glassmites feed on it, and climb it to its mouth on the
// overlook, the shrine and the whole city below you; down the grand stair into the Gate Court, and
// north of it Lantern Square and its moon pool, the Landing on the gorge's edge, the great
// bridge sunk in the gorge below it, and Lamplighters' Row east. The way over is the Glass
// Bridge at the west street's head, into the castle's postern; its bailey, the west chapel and the
// Duchess's pale garden; and at its heart the Cathedral of the Long Night, the nave and, behind its
// great door, the choir where the Duchess waits. Once she falls, her choir's back door opens on the
// old stair up through its east wall, the gallery along the cathedral's flank over her garden and the
// bridge at its end over the garden's mouth, where the Argent Sigil she wed the moon on lies on the
// altar of Lyra the Embracer, older than the city. The great bridge's lever, in the bailey, is the
// short way back to the shrine.

